 reference(ch){const mode=(this.ccm(ch)>>>4)&7,cnt=this.phase();return mode===4?false:mode===5?true:mode===6?cnt<this.active.ccr[ch]:mode===7?cnt>=this.active.ccr[ch]:!!this.oc[ch];}
