 pads(ch){if(this.f4)return [['PA0','PA5','PA15'],['PA1','PB3'],['PA2','PB10'],['PA3','PB11']][ch];const map=((this.r.regs.get(0x40010004)||0)>>>8)&3;return [[map&1?'PA15':'PA0'],[map&1?'PB3':'PA1'],[map&2?'PB10':'PA2'],[map&2?'PB11':'PA3']][ch];}
 mapped(pin,input=false){if(!pin||!this.r.board.gpio.includes(pin))return false;const n=+pin.slice(2),bank=pin.charCodeAt(1)-65,base=(this.f4?0x40020000:0x40010800)+bank*1024;if(this.f4)return !!(this.r.regs.get(0x40023830)&(1<<bank))&&((this.r.regs.get(base)>>>n*2)&3)===2&&((this.r.regs.get(base+32+(n>=8?4:0))>>>((n%8)*4))&15)===1;const c=(this.r.regs.get(base+(n<8?0:4))>>>((n%8)*4))&15;return !!(this.r.regs.get(0x40021018)&(1<<(bank+2)))&&(input?!(c&3)&&[1,2].includes(c>>>2):!!(c&3)&&(c>>>2)===2);}
